module circle_dance(\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] p_0,\n    input [7:0] p_1,\n    input [7:0] p_2,\n    input [7:0] p_3,\n    output reg [7:0] result_0,\n    output reg [7:0] result_1,\n    output reg [7:0] result_2,\n    output reg [7:0] result_3,\n    output reg done,\n    output reg valid\n);\n    localparam [1:0] IDLE    = 2'd0;\n    localparam [1:0] SEARCH  = 2'd1;\n    localparam [1:0] OUTPUT  = 2'd2;\n    \n    reg [1:0] state;\n    reg [3:0] count;\n    reg [3:0] dir_combo;\n    \n    wire [1:0] pos0, pos1, pos2, pos3;\n    wire valid_combo;\n    wire pos0_eq_pos1 = (pos0 == pos1);\n    wire pos0_eq_pos2 = (pos0 == pos2);\n    wire pos0_eq_pos3 = (pos0 == pos3);\n    wire pos1_eq_pos2 = (pos1 == pos2);\n    wire pos1_eq_pos3 = (pos1 == pos3);\n    wire pos2_eq_pos3 = (pos2 == pos3);\n    \n    assign valid_combo = !(pos0_eq_pos1 || pos0_eq_pos2 || pos0_eq_pos3 || \n                           pos1_eq_pos2 || pos1_eq_pos3 || pos2_eq_pos3);\n    \n    assign pos0 = dir_combo[0] ? (2'd0 - p_0[1:0]) : (2'd0 + p_0[1:0]);\n    assign pos1 = dir_combo[1] ? (2'd1 - p_1[1:0]) : (2'd1 + p_1[1:0]);\n    assign pos2 = dir_combo[2] ? (2'd2 - p_2[1:0]) : (2'd2 + p_2[1:0]);\n    assign pos3 = dir_combo[3] ? (2'd3 - p_3[1:0]) : (2'd3 + p_3[1:0]);\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            valid <= 1'b0;\n            count <= 4'd0;\n            dir_combo <= 4'd0;\n            result_0 <= 8'd0;\n            result_1 <= 8'd0;\n            result_2 <= 8'd0;\n            result_3 <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    valid <= 1'b0;\n                    dir_combo <= 4'd0;\n                    count <= 4'd0;\n                    if (start) state <= SEARCH;\n                end\n                \n                SEARCH: begin\n                    dir_combo <= count;\n                    count <= count + 4'd1;\n                    \n                    if (valid_combo) begin\n                        valid <= 1'b1;\n                        state <= OUTPUT;\n                    end else if (count == 4'd15) begin\n                        valid <= 1'b0;\n                        state <= OUTPUT;\n                    end\n                end\n                \n                OUTPUT: begin\n                    result_0 <= (dir_combo[0] ? 8'h52 : 8'h4C);\n                    result_1 <= (dir_combo[1] ? 8'h52 : 8'h4C);\n                    result_2 <= (dir_combo[2] ? 8'h52 : 8'h4C);\n                    result_3 <= (dir_combo[3] ? 8'h52 : 8'h4C);\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule\n